def deer(model, prompt, lam=0.95):
    trace = prompt + "<think>"
    while True:
        trace += model.generate(trace, stop="Wait")
        if model.ended_thinking(trace):
            return model.answer(trace)
        trial = model.generate(trace + INDUCER)
        conf = geo_mean(trial.max_token_probs)
        if conf > lam:                  # confident enough
            return model.answer(trace + "</think>")
        trace += "Wait"                 # drop the trial, keep thinking

import math

def confidence(token_probs, kind="geo"):
    """Max-probability of each trial-answer token, averaged."""
    if kind == "geo":   # DEER: geometric mean
        return math.exp(sum(math.log(p) for p in token_probs) / len(token_probs))
    return sum(token_probs) / len(token_probs)  # arithmetic (DEER-AM)

LAMBDA = 0.95
# trial answers induced at three successive "Wait" points (illustrative)
trials = {
