}
for name, probs in trials.items():
    g, a = confidence(probs), confidence(probs, "arith")
    print(f"{name:16} geo={g:.3f} arith={a:.3f} "
          f"exit(geo)={g > LAMBDA} exit(arith)={a > LAMBDA}")
